import threading

def reproduce(connect, service) -> str | None:
    N = 6
    AMOUNT = 1000
    ACCOUNT = 1
    barrier = threading.Barrier(N)
    errors = []

    def worker():
        try:
            barrier.wait(timeout=10)
        except Exception as e:
            return
        try:
            with connect() as conn:
                try:
                    service.withdraw(conn, ACCOUNT, AMOUNT)
                except service.DailyLimitExceeded:
                    pass
                except Exception:
                    # catch ValueError, psycopg errors (e.g. check violation) so test doesn't escape
                    pass
        except Exception:
            pass

    threads = [threading.Thread(target=worker) for _ in range(N)]
    for t in threads:
        t.start()
    for t in threads:
        t.join(timeout=30)

    # read total withdrawn today for the account
    try:
        with connect() as conn:
            with conn.cursor() as cur:
                cur.execute("SELECT COALESCE(SUM(amount),0) FROM withdrawals WHERE account_id=%s AND day=current_date", (ACCOUNT,))
                row = cur.fetchone()
                total = int(row[0]) if row else 0
    except Exception as e:
        return None
    limit = getattr(service, "DAILY_LIMIT", 5000)
    if total > limit:
        return f"account {ACCOUNT} withdrew {total} today, above the daily limit of {limit}"
    return None
